<?php
declare(strict_types=1); namespace TmsAi\Services; use TmsAi\Core\App;
final class GatewayService { public function __construct(private ProviderService $providers,private UsageService $usage){} public function chat(array$p,array$client):array{$model=trim((string)($p['model']??''));if($model==='')return['status'=>400,'body'=>['error'=>['message'=>'model là bắt buộc.','type'=>'invalid_request_error']]];if(!empty($p['stream']))return['status'=>400,'body'=>['error'=>['message'=>'Streaming SSE sẽ được bổ sung ở bản tiếp theo.','type'=>'unsupported_feature']]];$routes=$this->routes($model);if(!$routes)return['status'=>404,'body'=>['error'=>['message'=>'Không có provider cho model: '.$model,'type'=>'model_not_found']]];$rid='tmsreq_'.bin2hex(random_bytes(10));$last=null;foreach($routes as$r){$pid=(int)$r['provider_id'];if(!$this->usage->providerAllowed($pid))continue;$prov=$this->providers->find($pid);if(!$prov||empty($prov['enabled']))continue;$up=$p;$up['model']=$r['upstream_model'];$start=microtime(true);$resp=$this->post(rtrim($prov['base_url'],'/').'/chat/completions',$up,(string)$prov['api_key'],(int)$prov['timeout_seconds']);$lat=(int)round((microtime(true)-$start)*1000);$body=json_decode($resp['body'],true);$u=is_array($body)&&is_array($body['usage']??null)?$body['usage']:[];$in=(int)($u['prompt_tokens']??$u['input_tokens']??0);$out=(int)($u['completion_tokens']??$u['output_tokens']??0);$total=(int)($u['total_tokens']??($in+$out));$source=($in||$out||$total)?'provider':'estimated';if($source==='estimated'&&is_array($body)){$in=$this->estimate($p['messages']??[]);$out=$this->estimate($body['choices']??[]);$total=$in+$out;}$ok=$resp['status']>=200&&$resp['status']<300;$this->usage->record(['request_id'=>$rid,'provider_id'=>$pid,'client_key_id'=>(int)$client['id'],'model'=>$model,'upstream_model'=>$r['upstream_model'],'input_tokens'=>$in,'output_tokens'=>$out,'total_tokens'=>$total,'usage_source'=>$source,'status_code'=>$resp['status'],'latency_ms'=>$lat,'success'=>$ok]);if($ok&&is_array($body)){header('X-TMS-Provider: '.rawurlencode((string)$prov['name']));header('X-TMS-Request-Id: '.$rid);return['status'=>$resp['status'],'body'=>$body];}$last=is_array($body)?$body:['error'=>['message'=>'Upstream HTTP '.$resp['status']]];if(!in_array($resp['status'],[408,409,425,429,500,502,503,504],true))break;}return['status'=>502,'body'=>$last?:['error'=>['message'=>'Không còn provider khả dụng.','type'=>'upstream_unavailable']]];}
private function routes(string$model):array{$strategy=App::db()->querySingle("SELECT value FROM settings WHERE key='routing_strategy'")?:'priority';$sql='SELECT pm.provider_id,pm.upstream_model,p.priority FROM provider_models pm JOIN providers p ON p.id=pm.provider_id WHERE pm.enabled=1 AND p.enabled=1 AND pm.public_model=:m ';if(in_array($strategy,['least_used','quota_first'],true))$sql.='ORDER BY (SELECT COALESCE(SUM(total_tokens),0) FROM usage_events u WHERE u.provider_id=p.id AND u.created_at>='.strtotime('today').') ASC,p.priority ASC';elseif($strategy==='round_robin')$sql.='ORDER BY (SELECT COALESCE(MAX(created_at),0) FROM usage_events u WHERE u.provider_id=p.id) ASC,p.priority ASC';else$sql.='ORDER BY p.priority,p.id';$s=App::db()->prepare($sql);$s->bindValue(':m',$model,SQLITE3_TEXT);$r=$s->execute();$o=[];while($x=$r?->fetchArray(SQLITE3_ASSOC))$o[]=$x;return$o;}
private function post(string$url,array$p,string$key,int$timeout):array{if(!function_exists('curl_init'))return['status'=>500,'body'=>json_encode(['error'=>['message'=>'PHP cURL chưa được cài.']])];$ch=curl_init($url);$headers=['Content-Type: application/json','Accept: application/json','User-Agent: TMS-AI-Router/'.App::config('version','1.0.0')];if($key!=='')$headers[]='Authorization: Bearer '.$key;curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>(int)App::config('connect_timeout',15),CURLOPT_TIMEOUT=>max(10,$timeout),CURLOPT_HTTPHEADER=>$headers,CURLOPT_POSTFIELDS=>json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);if($body===false){$body=json_encode(['error'=>['message'=>curl_error($ch),'type'=>'upstream_transport_error']]);if($status===0)$status=502;}curl_close($ch);return['status'=>$status?:502,'body'=>(string)$body];} private function estimate(mixed$x):int{$t=json_encode($x,JSON_UNESCAPED_UNICODE);$len=function_exists('mb_strlen')?mb_strlen((string)$t,'UTF-8'):strlen((string)$t);return max(0,(int)ceil($len/4));}}
